import{_ as e}from"./chunks/popup-translate.Bz3dSJPd.js";import{_ as a}from"./chunks/page-selection.B_Erd84k.js";import{_ as o}from"./chunks/page-dock.SoVsk_6G.js";import{_ as s,o as n,c as i,a2 as r}from"./chunks/framework.CfwCq2QB.js";const _=JSON.parse('{"title":"Quick start (5 minutes)","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/quick-start.md","filePath":"en/guide/quick-start.md"}'),l={name:"en/guide/quick-start.md"};function d(c,t,p,h,u,g){return n(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="quick-start-5-minutes" tabindex="-1">Quick start (5 minutes) <a class="header-anchor" href="#quick-start-5-minutes" aria-label="Permalink to &quot;Quick start (5 minutes)&quot;">​</a></h1><p>Three things to try after installing DevGo — they cover the core of what it does.</p><h2 id="_1-full-page-bilingual-translation" tabindex="-1">1. Full-page bilingual translation <a class="header-anchor" href="#_1-full-page-bilingual-translation" aria-label="Permalink to &quot;1. Full-page bilingual translation&quot;">​</a></h2><p><strong>What it does</strong>: translates the whole page, with each translation placed right after the original paragraph.</p><p><strong>How</strong>: open any page in a foreign language, then pick one —</p><ul><li>Toolbar icon → Translate page → &quot;Translate this page&quot;</li><li>Right-click an empty spot → &quot;Translate this page (click again to restore the original)&quot;</li><li>Bind a shortcut for &quot;Toggle page translation&quot; at <code>chrome://extensions/shortcuts</code></li></ul><p>Translations load as you scroll — long pages don&#39;t wait for the whole thing. Click &quot;Show original&quot; to restore.</p><img src="'+e+'" alt="The popup&#39;s Translate page" style="width:60%;display:block;margin-left:auto;margin-right:auto;"><p><em>The popup&#39;s Translate page: &quot;Translate this page&quot; starts the bilingual view; translations load as you scroll.</em></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The default engine is Microsoft (works without a proxy). You can switch to Google or your own AI model — see <a href="/dev-go-docs/en/features/page-translate.html">Full-page bilingual translation</a>.</p></div><h2 id="_2-selection-translation-and-ai-actions" tabindex="-1">2. Selection translation and AI actions <a class="header-anchor" href="#_2-selection-translation-and-ai-actions" aria-label="Permalink to &quot;2. Selection translation and AI actions&quot;">​</a></h2><p><strong>What it does</strong>: select text and a toolbar appears — no page navigation needed.</p><p><strong>How</strong>: select text on a page —</p><ul><li>On page text: <strong>Translate / Explain / Summarize / Ask AI</strong>; selecting a single English word also shows dictionary definitions</li><li>In input fields: <strong>Polish / Fix / Formal</strong>, plus custom actions that apply to inputs; AI results can replace the original text in one click</li><li>Need more actions? Add your own under Settings → Selection → Toolbar actions (e.g. &quot;Convert to JSON&quot;, &quot;Explain the error&quot;) — just a name and a prompt</li></ul><img src="'+a+'" alt="Selection toolbar"><p><em>The toolbar that appears when you select text: Translate / Explain / Summarize / Ask AI.</em></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>AI actions need a model first — see <a href="/dev-go-docs/en/settings/models.html">AI models</a>. Find the toolbar distracting? Turn it off for just the current site from the popup&#39;s Features page.</p></div><h2 id="_3-floating-dock" tabindex="-1">3. Floating dock <a class="header-anchor" href="#_3-floating-dock" aria-label="Permalink to &quot;3. Floating dock&quot;">​</a></h2><p><strong>What it does</strong>: a slim dark strip on the right edge of every page; hover to expand quick actions.</p><p><strong>How</strong>: move the pointer to the right edge —</p><ul><li><strong>Translate this page / Show original</strong>: toggle full-page translation</li><li><strong>AI summary</strong>: opens the side panel and starts summarizing</li><li><strong>AI assistant</strong>: opens the side panel chat</li><li><strong>Back to top</strong>: appears after you scroll down a bit</li></ul><p>The dock can be dragged up and down. Click the × at its corner to hide it — for now, on this site, or on all sites.</p><img src="'+o+'" alt="Floating dock"><p><em>The floating dock on the right edge, expanded on hover.</em></p><h2 id="default-shortcuts" tabindex="-1">Default shortcuts <a class="header-anchor" href="#default-shortcuts" aria-label="Permalink to &quot;Default shortcuts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Alt+1</code> (<code>⌥1</code> on macOS)</td><td>Open the popup (default page)</td></tr><tr><td><code>Alt+2</code> (<code>⌥2</code> on macOS)</td><td>Open / close the side panel AI assistant</td></tr><tr><td><code>Alt+3</code> (<code>⌥3</code> on macOS)</td><td>Open the popup&#39;s Network page</td></tr><tr><td><code>Alt+4</code> (<code>⌥4</code> on macOS)</td><td>Open the popup&#39;s Resources page</td></tr><tr><td>Not bound</td><td>Toggle page translation (bindable at <code>chrome://extensions/shortcuts</code>)</td></tr></tbody></table><p>All shortcuts are customizable — see <a href="/dev-go-docs/en/settings/general.html#shortcuts">General &amp; appearance</a>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Configure <a href="/dev-go-docs/en/settings/models.html">AI models</a> to unlock AI explain, summarize, polish, and the side panel assistant</li><li>Browsing through a proxy? Read up on <a href="/dev-go-docs/en/features/ip-protection.html">Real IP protection</a></li><li>Want the AI to act on pages? See <a href="/dev-go-docs/en/features/webmcp.html">Page tools (WebMCP)</a></li></ul>',29)])])}const q=s(l,[["render",d]]);export{_ as __pageData,q as default};
